use serde_json::{json,Value};
use tron_apis::{JsonRpcBackend,JsonRpcError,JsonRpcLimits,JsonRpcProcessor};
struct Echo;
impl JsonRpcBackend for Echo { fn execute(&self,m:&str,p:&Value)->Result<Value,JsonRpcError>{if m=="echo"{Ok(p.clone())}else{Err(JsonRpcError::method_not_found())}} }
fn body(response:&tron_apis::JsonRpcHttpResponse)->Value{serde_json::from_slice(&response.body).unwrap()}
#[test] fn single_batch_notification_and_ids(){let p=JsonRpcProcessor::new(Echo,JsonRpcLimits::default());let r=p.handle_post(br#"{"jsonrpc":"2.0","method":"echo","params":[1],"id":"x"}"#);assert_eq!(r.status,200);assert_eq!(r.content_type,"application/json-rpc");assert_eq!(body(&r),json!({"jsonrpc":"2.0","result":[1],"id":"x"}));assert!(p.handle_post(br#"{"jsonrpc":"2.0","method":"echo"}"#).body.is_empty());let r=p.handle_post(br#"[{"jsonrpc":"2.0","method":"echo","id":1},9,{"jsonrpc":"2.0","method":"echo"}]"#);assert_eq!(body(&r),json!([{"jsonrpc":"2.0","result":[],"id":1},{"jsonrpc":"2.0","error":{"code":-32600,"message":"Invalid Request"},"id":null}]));}
#[test] fn parse_request_batch_and_response_limits_are_http_200(){let mut l=JsonRpcLimits::default();l.max_batch_size=1;let p=JsonRpcProcessor::new(Echo,l);let r=p.handle_post(b"{");assert_eq!(r.status,200);assert_eq!(body(&r)["error"]["code"],-32700);let r=p.handle_post(b"[]");assert_eq!(body(&r)["error"]["code"],-32600);let r=p.handle_post(br#"[{"jsonrpc":"2.0","method":"echo","id":1},{"jsonrpc":"2.0","method":"echo","id":2}]"#);assert_eq!(body(&r)[0]["error"]["code"],-32005);}
#[test] fn invalid_id_is_invalid_request_with_null_id(){let p=JsonRpcProcessor::new(Echo,JsonRpcLimits::default());let r=p.handle_post(br#"{"jsonrpc":"2.0","method":"echo","id":true}"#);assert_eq!(body(&r),json!({"jsonrpc":"2.0","error":{"code":-32600,"message":"Invalid Request"},"id":null}));}
